//! The motor and ESC study (#19): the published table matches the code, every check passes and
//! states why its tolerance suits the step, and the study fails when a check does.

use mjk_aero::propulsion::{EscError, MotorError};
use mjk_dynamics::RateError;
use mjk_sim::validation::check::{Check, Measure, markdown};
use mjk_sim::validation::motor::{MotorStudyError, motor_study, passed, test_motor};

/// The table the book includes, generated by `mjk validate motor`.
const PUBLISHED: &str = include_str!("../../../docs/src/validation/motor.md");

#[test]
fn the_published_table_matches_the_code() {
    let checks = motor_study().expect("the study runs");
    assert_eq!(markdown(&checks), PUBLISHED);
}

#[test]
fn every_check_passes_and_states_why() {
    let checks = motor_study().expect("the study runs");
    assert_eq!(checks.len(), 13);
    for check in &checks {
        assert!(check.passed(), "{check:?}");
        assert!(!check.why.is_empty(), "{}", check.name);
    }
    assert!(passed(&checks));
}

#[test]
fn the_study_fails_if_a_check_does() {
    let mut checks = motor_study().expect("the study runs");
    let small_signal = checks
        .iter_mut()
        .find(|check| check.name.starts_with("Small-signal"))
        .expect("the small-signal check");
    small_signal.error = 2.0 * small_signal.tolerance;
    assert!(!passed(&checks));
    assert!(markdown(&checks).contains("| Fail |"));
}

#[test]
fn the_acceptance_criteria_are_in_the_table() {
    let checks = motor_study().expect("the study runs");
    let names: Vec<&str> = checks.iter().map(|check| check.name.as_str()).collect();
    assert!(names.contains(&"Steady speed, constant load 0.05 N·m"));
    assert!(names.contains(&"Small-signal time constant, 1 % step at 80 % duty"));
    let tau = checks
        .iter()
        .find(|check| check.name.starts_with("Small-signal"))
        .expect("the small-signal check");
    assert_eq!(tau.measure, Measure::Relative);
    assert!(
        tau.error < 1e-3,
        "matches the linearized time constant within 0.1 %: {}",
        tau.error
    );
}

#[test]
fn counts_are_compared_as_whole_numbers() {
    let exact = Check::count("latency", 3, 3, "ticks").with_tolerance(0.0, "exact".to_owned());
    assert_eq!(exact.measure, Measure::Count("ticks"));
    assert!(exact.passed());
    let off = Check::count("latency", 3, 5, "ticks").with_tolerance(0.0, "exact".to_owned());
    assert!((off.error - 2.0).abs() < f64::EPSILON);
    assert!(!off.passed());
    let backward = Check::count("latency", 5, 3, "ticks");
    assert!((backward.error - 2.0).abs() < f64::EPSILON);
    let table = markdown(&[exact, off]);
    assert!(
        table.contains("| 1 | latency | 3 | 3 | 0 ticks | 0 ticks | Pass |"),
        "{table}"
    );
    assert!(
        table.contains("| 2 | latency | 3 | 5 | 2 ticks | 0 ticks | Fail |"),
        "{table}"
    );
    assert!(
        !table.contains("Vector checks"),
        "no vector checks, no note"
    );
}

#[test]
fn the_test_motor_is_the_published_one() {
    let motor = test_motor().expect("usable");
    assert!((motor.kv_rad_s_v() - 920.0 * 2.0 * core::f64::consts::PI / 60.0).abs() < 1e-12);
    assert!((motor.resistance_ohm() - 0.117).abs() < 1e-15);
    assert!((motor.time_constant_s(0.0) - 0.0923).abs() < 1e-4);
}

#[test]
fn errors_explain_themselves() {
    let motor = MotorError {
        name: "the resistance",
        value: 0.0,
        zero_allowed: false,
    };
    let cases = [
        (
            MotorStudyError::from(motor),
            "the test motor is not usable: the resistance must be positive and finite; found 0",
        ),
        (
            MotorStudyError::from(EscError::Rate),
            "the test ESC is not usable: the physics rate must be at least 1 Hz",
        ),
        (
            MotorStudyError::from(RateError::Zero),
            "the physics rate is not usable: a rate must be at least 1 Hz",
        ),
    ];
    for (error, message) in cases {
        assert_eq!(error.to_string(), message);
    }
}
